export type Snapshot = {
	id: string,
	project_id: string,
	/**  One plain line, unique in the project. */
	name: string,
	/**  The version it pins. */
	version: number,
	/**  Optional words about it; empty when none were given. */
	note: string,
	created_at_ms: number,
	/**
	 *  The print job whose sliced file the snapshot keeps; `null` when the version had not
	 *  been printed when the snapshot was made.
	 */
	printed_job_id?: string | null,
	/**  SHA-256 of that job's sliced file. */
	printed_sha256?: string | null,
};

/**  What `snapshot_export` wrote (`hotend_core::SnapshotExport`). */
export type SnapshotExport = {
	snapshot: Snapshot,
	/**  The new folder the files are in, below the folder the person chose. */
	folder: string,
	files: SnapshotFile[],
	printed: PrintedFile | null,
	printed_missing?: MissingPrinted | null,
};

/**  One file of a snapshot export (`hotend_core::SnapshotFile`). */
export type SnapshotFile = {
	/**
	 *  `step`, `3mf`, `printed` (the sliced file of the print) or `manifest`
	 *  (`snapshot.json`).
	 */
	kind: string,
	/**  `copied`, `exported` (made by `export_run`) or `written` (the manifest). */
	source: string,
	path: string,
	bytes: number,
	sha256: string,
};

export type SpoolChoice = {
	slot: number,
	material: string,
	nozzle_id: number,
	ams_unit: number,
	tray: number,
	loaded: string,
};

/**  The one spool the print settings plan with; its material is the settings' material. */
export type SpoolSettings = {
	/**  An AMS slot `1` to `16`, `external_main` or `external_auxiliary`. */
	slot: string,
	/**  `#rrggbb`; `null` until the person says, and grey (#898989) is then assumed. */
	colour: string | null,
	silk: boolean,
};

export type StopReason = "done" | "budget" | "cancelled" | "error";

/**  A temperature and its target, °C; a target of 0 means the heater is off. */
export type TemperatureReading = {
	current_c: number | null,
	target_c: number | null,
};

/**  One line of the stored conversation. */
export type TranscriptEntry = {
	id: number,
	run_id: string,
	/**  `user` or `assistant`. */
	role: string,
	text: string,
	at_ms: number,
	remembered: boolean,
};

export type TrayInfo = {
	id: number,
	material: string | null,
	product: string | null,
	colour: string | null,
	remaining_percent: number | null,
};

export type Unplaced = {
	name: string,
	part: string,
	copy: number,
	reason: string,
	/**  `clearance`, `keepout`, `too_large` or `no_reach`. */
	cause?: string | null,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

/**  One immutable build of the model. */
export type Version = {
	project_id: string,
	number: number,
	created_at_ms: number,
	parent: number | null,
	/**  `write_model_code` for a written model, `set_parameter` for one changed size. */
	origin: string,
	note: string,
	status: VersionStatus,
	code_sha256: string,
	params: { [key in string]: number },
};

export type VersionDetail = {
	version: Version,
	result: EngineResult,
	dir: string,
};

export type VersionStatus = "ok" | "check_error";

/**  A number of a version that came from a web page (`hotend_core::research::WebNumber`). */
export type WebNumber = {
	note: string,
	key: string,
	label: string,
	value: number,
	unit: string,
	/**  The page. Shown as text; opened only when the person asks. */
	url: string,
	host: string,
	title: string,
	quote: string,
	locator: string,
	/**  `page_text`, `citation` or `none`. */
	evidence: string,
	/**  `unconfirmed` or `confirmed`. */
	state: string,
	params: string[],
	built: number | null,
	text: string,
};
